function mapDataUrl(){return new Promise(function(resolve,reject){var root=document.getElementById('aiv-map'),svg=root&&root.querySelector('svg');if(!svg){reject(new Error('map unavailable'));return;}try{var clone=svg.cloneNode(true);clone.setAttribute('width','1400');clone.setAttribute('height','1400');var xml=new XMLSerializer().serializeToString(clone),blob=new Blob([xml],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),img=new Image();img.onload=function(){try{var canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1400;var ctx=canvas.getContext('2d');ctx.fillStyle='#0b0d10';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/png'));}catch(e){URL.revokeObjectURL(url);reject(e);}};img.onerror=function(){URL.revokeObjectURL(url);reject(new Error('map image error'));};img.src=url;}catch(e){reject(e);}});}
function mapAction(action){if(!state.plan){mapStatus(t.mapError,false);return;}mapStatus(t.mapWorking,false);mapDataUrl().then(function(data){var bridge=window.LightingAIImages,name=mapStamp();if(bridge&&typeof bridge.saveImage==='function'&&typeof bridge.shareImage==='function'){if(action==='share')bridge.shareImage(name,data,currentLanguage()==='sr'?'Podeli LightingAI tlocrt':'Share LightingAI setup map');else bridge.saveImage(name,data);mapStatus(action==='share'?t.mapShared:t.mapSaved,true);return;}if(action==='save'){var a=document.createElement('a');a.href=data;a.download=name;a.click();mapStatus(t.mapSaved,true);return;}mapStatus(t.mapError,false);}).catch(function(){mapStatus(t.mapError,false);});}
